import { chromium } from 'playwright';

const URL = process.argv[2] || 'http://127.0.0.1:5173/';
const browser = await chromium.launch({
  executablePath: '/home/node/.cache/ms-playwright/chromium_headless_shell-1148/chrome-linux/headless_shell',
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
});
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, colorScheme: 'light' });
// Окружение песочницы отдаёт navigator.language = "en-US@posix", что ломает Intl в Yagr. Подменяем только в тесте.
await ctx.addInitScript(() => {
  Object.defineProperty(Navigator.prototype, 'language', { get: () => 'en-US' });
  Object.defineProperty(Navigator.prototype, 'languages', { get: () => ['en-US'] });
  // Считаем живые таймеры и ResizeObserver, чтобы проверить освобождение ресурсов.
  const live = new Set();
  const si = window.setInterval, ci = window.clearInterval;
  window.setInterval = (...a) => { const id = si(...a); live.add(id); return id; };
  window.clearInterval = (id) => { live.delete(id); return ci(id); };
  window.__liveIntervals = () => live.size;
  let roLive = 0;
  const RO = window.ResizeObserver;
  window.ResizeObserver = class extends RO {
    constructor(cb) { super(cb); this.__observed = new Set(); }
    observe(el, o) { roLive++; this.__observed.add(el); return super.observe(el, o); }
    unobserve(el) { if (this.__observed.delete(el)) roLive--; return super.unobserve(el); }
    disconnect() { roLive -= this.__observed.size; this.__observed.clear(); return super.disconnect(); }
  };
  window.__liveRO = () => roLive;
  window.__longTasks = [];
  try { new PerformanceObserver((list) => { for (const e of list.getEntries()) window.__longTasks.push(e.duration); }).observe({ type: 'longtask', buffered: true }); } catch {}
});
const page = await ctx.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text().slice(0, 300)}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message.slice(0, 300)}`));

await page.goto(URL, { waitUntil: 'domcontentloaded', timeout: 30000 });
await page.waitForSelector('.cpu-chart canvas', { timeout: 20000 });
await page.waitForTimeout(2500);

const snap = (label) => page.evaluate((label) => ({
  label,
  panelTheme: document.querySelector('.cpu-panel').dataset.theme,
  chartRootClass: document.querySelector('.cpu-chart').className,
  chartSize: (() => { const r = document.querySelector('.cpu-chart').getBoundingClientRect(); return [Math.round(r.width), Math.round(r.height)]; })(),
  uplotInstances: document.querySelectorAll('.cpu-chart .uplot').length,
  canvases: document.querySelectorAll('.cpu-chart canvas').length,
  stats: [...document.querySelectorAll('.cpu-stats dd')].map((d) => d.textContent),
  tableRows: document.querySelectorAll('.cpu-table tbody tr').length,
  yAxisLabels: [...document.querySelectorAll('.cpu-chart .u-axis')].length,
  liveIntervals: window.__liveIntervals(),
  liveResizeObservers: window.__liveRO(),
}), label);

console.log('== LIGHT', JSON.stringify(await snap('light')));
await page.screenshot({ path: '/tmp/browsercheck/light.png' });

// Realtime: текущее значение меняется, график не пересоздаётся.
const s1 = await page.textContent('.cpu-stats dd');
await page.waitForTimeout(7000);
const s2 = await page.textContent('.cpu-stats dd');
const lt = await page.evaluate(() => window.__longTasks.slice());
console.log('== REALTIME current before/after 7s:', s1, '->', s2, '| long tasks (ms):', JSON.stringify(lt.map((x) => Math.round(x))));
console.log('== uplot instances after 7s of updates:', await page.evaluate(() => document.querySelectorAll('.cpu-chart .uplot').length));

// Адаптивность: контейнер растягивается.
await page.setViewportSize({ width: 1600, height: 1000 });
await page.waitForTimeout(800);
console.log('== RESIZE 1600x1000 chart size:', JSON.stringify(await page.evaluate(() => { const r = document.querySelector('.cpu-chart').getBoundingClientRect(); return [Math.round(r.width), Math.round(r.height)]; })));
await page.setViewportSize({ width: 1280, height: 800 });
await page.waitForTimeout(500);

// Тёмная тема: график пересоздаётся (dispose старого), дубликатов быть не должно.
const intervalsBefore = await page.evaluate(() => window.__liveIntervals());
const roBefore = await page.evaluate(() => window.__liveRO());
await page.emulateMedia({ colorScheme: 'dark' });
await page.waitForTimeout(1500);
console.log('== DARK', JSON.stringify(await snap('dark')));
await page.screenshot({ path: '/tmp/browsercheck/dark.png' });

// Многократное переключение: ресурсы не должны копиться.
for (let i = 0; i < 4; i++) {
  await page.emulateMedia({ colorScheme: i % 2 ? 'dark' : 'light' });
  await page.waitForTimeout(400);
}
await page.emulateMedia({ colorScheme: 'dark' });
await page.waitForTimeout(800);
const after = await snap('after-toggles');
console.log('== AFTER 5 theme toggles', JSON.stringify(after));
console.log('== DELTA intervals:', after.liveIntervals - intervalsBefore, ' ResizeObserver:', after.liveResizeObservers - roBefore);

console.log('== ERRORS', JSON.stringify(errors, null, 1));
await browser.close();
EOF
