2	import Yagr, { type AreaSeriesOptions, type MinimalValidConfig, type RawSerieData } from '@gravity-ui/yagr';
3	import '@gravity-ui/yagr/index.css';
4	
5	import type { CpuFeed } from './cpuFeed';
6	
7	export type ChartTheme = 'light' | 'dark';
8	
9	const SERIES_ID = 'cpu';
10	/** Слот 1 категориальной палитры (blue): линия — сплошная, заливка — подложка ~10%. */
11	const SERIES_STYLE: Record<ChartTheme, { line: string; fill: string }> = {
12	  light: { line: '#2a78d6', fill: 'rgba(42, 120, 214, 0.1)' },
13	  dark: { line: '#3987e5', fill: 'rgba(57, 135, 229, 0.1)' },
14	};
15	const AXIS_FONT = '11px system-ui, -apple-system, "Segoe UI", sans-serif';
16	
17	function createSeries(feed: CpuFeed, theme: ChartTheme): RawSerieData<AreaSeriesOptions> {
18	  const style = SERIES_STYLE[theme];
19	  return {
20	    id: SERIES_ID,
21	    name: 'CPU',
22	    type: 'area',
23	    // В Yagr для area заливка берётся из color, а контур из lineColor (по умолчанию тёмный).
24	    color: style.fill,
25	    lineColor: style.line,
26	    lineWidth: 2,
27	    precision: 1,
28	    formatter: (value) => (value == null ? '' : `${Number(value).toFixed(1)}%`),
29	    data: feed.values.slice(),
30	  };
31	}
32	
33	const timeLabel = (t: number) => new Date(t).toLocaleTimeString('ru-RU');
34	
35	function createConfig(feed: CpuFeed, theme: ChartTheme): MinimalValidConfig {
36	  return {
37	    chart: {
38	      appearance: { theme, locale: 'ru' },
39	      size: { adaptive: true, resizeDebounceMs: 100 },
40	    },
41	    timeline: feed.timeline.slice(),
42	    series: [createSeries(feed, theme)],
43	    // Одна серия: легенда не нужна, заголовок страницы называет показатель.
44	    legend: { show: false },
45	    // Нейтральный crosshair из токенов панели. Цвет Yagr по умолчанию красный, а красный
46	    // в палитре зарезервирован за статусом «critical».
47	    cursor: {
48	      x: { visible: true, style: '1px solid var(--cpu-ink-3)' },
49	      y: { visible: false },
50	    },
51	    tooltip: {
52	      title: (data) => timeLabel(data.x),
53	    },
54	    scales: {
55	      x: { time: true },
56	      y: { min: 0, max: 100 },
57	    },
58	    axes: {
59	      x: { scale: 'x', font: AXIS_FONT },
60	      y: {
61	        scale: 'y',
62	        font: AXIS_FONT,
63	        splitsCount: 5,
64	        precision: 0,
65	        values: (_u, splits) => splits.map((v) => `${v}%`),
66	      },
67	    },
68	  };
69	}
70	
71	interface CpuChartProps {
72	  feed: CpuFeed;
73	  theme: ChartTheme;
74	}
75	
76	function CpuChartView({ feed, theme }: CpuChartProps) {
77	  const rootRef = useRef<HTMLDivElement>(null);
78	
79	  useEffect(() => {
80	    const root = rootRef.current;
81	    if (!root) {
82	      return;
83	    }
84	    // Тема задаётся при создании: смена темы пересоздаёт график. Это редкое
85	    // событие, и так не нужно сверять внутренние цвета Yagr с новой палитрой.
86	    const chart = new Yagr(root, createConfig(feed, theme));
87	
88	    // Скользящее окно фиксированной длины: одна точка добавляется, одна удаляется.
89	    // Такой путь обновляет график без полного пересоздания uPlot.
90	    const unsubscribe = feed.subscribe((sample) => {
91	      chart.setSeries([sample.t], [{ id: SERIES_ID, data: [sample.v] }], {
92	        incremental: true,
93	        splice: true,
94	      });
95	    });
96	
97	    return () => {
98	      unsubscribe();
99	      chart.dispose();
100	    };
101	  }, [feed, theme]);
102	
103	  return (
104	    <div
105	      ref={rootRef}
106	      className="cpu-chart"
107	      role="img"
108	      aria-label="График загрузки CPU за последние сутки"
109	    />
110	  );
111	}
112	
113	/** memo: родитель перерисовывается на каждом замере, а сам график — только при смене feed или темы. */
114	export const CpuChart = memo(CpuChartView);
115

