import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-gpu'] });
const logs = [];
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, colorScheme: 'light' });
const page = await ctx.newPage();
page.on('console', (m) => { if (['error', 'warning'].includes(m.type())) logs.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));

await page.goto(URL, { waitUntil: 'networkidle' });
await page.waitForSelector('.cpu-chart canvas', { timeout: 15000 });
await page.waitForTimeout(3000);

const info = await page.evaluate(() => {
  const root = document.querySelector('.cpu-chart');
  const r = root.getBoundingClientRect();
  const panel = document.querySelector('.cpu-panel').getBoundingClientRect();
  return {
    rootClass: root.className,
    rootSize: [Math.round(r.width), Math.round(r.height)],
    panelSize: [Math.round(panel.width), Math.round(panel.height)],
    uplotCount: document.querySelectorAll('.uplot').length,
    canvasCount: document.querySelectorAll('.cpu-chart canvas').length,
    panelTheme: document.querySelector('.cpu-panel').dataset.theme,
    stats: [...document.querySelectorAll('.cpu-stats dd')].map((d) => d.textContent),
    tableRows: document.querySelectorAll('.cpu-table tbody tr').length,
    yLabels: [...document.querySelectorAll('.u-axis')].slice(0, 2).map((a) => a.textContent.slice(0, 80)),
  };
});
console.log('LIGHT', JSON.stringify(info, null, 1));
await page.screenshot({ path: '/tmp/browsercheck/light.png' });

// Realtime check: stats change over time, and the page stays responsive.
const before = await page.evaluate(() => document.querySelector('.cpu-stats dd').textContent);
await page.waitForTimeout(6500);
const after = await page.evaluate(() => document.querySelector('.cpu-stats dd').textContent);
console.log('CURRENT before/after 6.5s:', before, after);

// Theme switch: chart must be recreated (not duplicated) and recolored.
await page.emulateMedia({ colorScheme: 'dark' });
await page.waitForTimeout(1500);
const dark = await page.evaluate(() => ({
  panelTheme: document.querySelector('.cpu-panel').dataset.theme,
  uplotCount: document.querySelectorAll('.uplot').length,
  yagrClasses: document.querySelector('.cpu-chart').className,
}));
console.log('DARK', JSON.stringify(dark));
await page.screenshot({ path: '/tmp/browsercheck/dark.png' });

// Unmount: navigating away should not leave timers or charts behind.
const hasTimersLeft = await page.evaluate(() => new Promise((res) => setTimeout(() => res('ok'), 10)));
console.log('LOGS', JSON.stringify(logs, null, 1));
await browser.close();
EOF
